target=root/'src/test/java/com/revature/project0/springjdbc/SpringTransactionalOfferWorkflowIntegrationTest.java'
target.parent.mkdir(parents=True,exist_ok=True)
target.write_text('package com.revature.project0.springjdbc;\n\nimport com.revature.project0.Project0Application;\nimport com.revature.project0.app.OfferAcceptanceService;\nimport com.revature.project0.domain.Offer;\nimport com.revature.project0.domain.OfferStatus;\nimport com.revature.project0.domain.Role;\nimport com.revature.project0.domain.User;\nimport com.revature.project0.domain.Vehicle;\nimport com.revature.project0.repository.OfferRepository;\nimport com.revature.project0.repository.PurchaseRepository;\nimport com.revature.project0.repository.UserRepository;\nimport com.revature.project0.repository.VehicleRepository;\nimport java.math.BigDecimal;\nimport java.util.UUID;\nimport java.util.concurrent.CountDownLatch;\nimport java.util.concurrent.ExecutorService;\nimport java.util.concurrent.Executors;\nimport java.util.concurrent.Future;\nimport org.junit.jupiter.api.BeforeEach;\nimport org.junit.jupiter.api.Test;\nimport org.springframework.beans.factory.annotation.Autowired;\nimport org.springframework.boot.test.context.SpringBootTest;\nimport org.springframework.jdbc.core.JdbcTemplate;\nimport static org.junit.jupiter.api.Assertions.*;\n\n@SpringBootTest(\n        classes = Project0Application.class,\n        webEnvironment = SpringBootTest.WebEnvironment.NONE,\n        properties = {\n            "spring.main.web-application-type=none",\n            "project0.bootstrap-admin.username=",\n            "project0.bootstrap-admin.password="\n        })\nclass SpringTransactionalOfferWorkflowIntegrationTest {\n    @Autowired OfferAcceptanceService workflow;\n    @Autowired UserRepository users;\n    @Autowired VehicleRepository vehicles;\n    @Autowired OfferRepository offers;\n    @Autowired PurchaseRepository purchases;\n    @Autowired JdbcTemplate jdbc;\n\n    @BeforeEach\n    void clean() {\n        jdbc.update("DELETE FROM outbox_event");\n        jdbc.update("DELETE FROM audit_event");\n        jdbc.update("DELETE FROM idempotency_record");\n        jdbc.update("DELETE FROM auth_session");\n        jdbc.update("DELETE FROM purchase");\n        jdbc.update("DELETE FROM offer");\n        jdbc.update("DELETE FROM vehicle");\n        jdbc.update("DELETE FROM app_user");\n    }\n\n    @Test\n    void repeatedIdempotencyKeyReturnsSamePurchaseAndSingleSideEffects() {\n        Fixture f = fixtureTwoOffers();\n\n        var first = workflow.accept(f.employee().getId(), f.first().getId(), 36, "idem-repeat-1");\n        var repeated = workflow.accept(f.employee().getId(), f.first().getId(), 36, "idem-repeat-1");\n\n        assertEquals(first.getId(), repeated.getId());\n        assertEquals(1, purchases.findAll().size());\n        assertEquals(1L, count("audit_event", "event_type=\'OFFER_ACCEPTED\'"));\n        assertEquals(1L, count("outbox_event", "event_type=\'OfferAccepted\'"));\n        assertEquals("COMPLETED",\n                jdbc.queryForObject(\n                        "SELECT state FROM idempotency_record WHERE idempotency_key=? AND operation=\'ACCEPT_OFFER\'",\n                        String.class,\n                        "idem-repeat-1"));\n    }\n\n    @Test\n    void competingConcurrentAcceptanceCannotCreateTwoPurchases() throws Exception {\n        Fixture f = fixtureTwoOffers();\n        CountDownLatch ready = new CountDownLatch(2);\n        CountDownLatch go = new CountDownLatch(1);\n\n        try (ExecutorService pool = Executors.newVirtualThreadPerTaskExecutor()) {\n            Future<Result> a = pool.submit(() -> invokeAfterBarrier(\n                    ready, go, f.employee().getId(), f.first().getId(), "race-a"));\n            Future<Result> b = pool.submit(() -> invokeAfterBarrier(\n                    ready, go, f.employee().getId(), f.second().getId(), "race-b"));\n\n            ready.await();\n            go.countDown();\n\n            Result ra = a.get();\n            Result rb = b.get();\n\n            assertEquals(1, (ra.success() ? 1 : 0) + (rb.success() ? 1 : 0),\n                    () -> "exactly one acceptance must succeed: a=" + ra + ", b=" + rb);\n        }\n\n        assertEquals(1, purchases.findAll().size());\n        assertFalse(vehicles.findById(f.vehicle().getId()).orElseThrow().isAvailable());\n\n        long accepted = offers.findAll().stream().filter(o -> o.getStatus() == OfferStatus.ACCEPTED).count();\n        long rejected = offers.findAll().stream().filter(o -> o.getStatus() == OfferStatus.REJECTED).count();\n        assertEquals(1, accepted);\n        assertEquals(1, rejected);\n        assertEquals(1L, count("audit_event", "event_type=\'OFFER_ACCEPTED\'"));\n        assertEquals(1L, count("outbox_event", "event_type=\'OfferAccepted\'"));\n        assertEquals(1L, count("idempotency_record", "state=\'COMPLETED\'"));\n    }\n\n    private Result invokeAfterBarrier(\n            CountDownLatch ready, CountDownLatch go, UUID employee, UUID offer, String key) {\n        ready.countDown();\n        try {\n            go.await();\n            return new Result(true, workflow.accept(employee, offer, 36, key).getId(), null);\n        } catch (Throwable t) {\n            return new Result(false, null, t.getClass().getSimpleName() + ":" + t.getMessage());\n        }\n    }\n\n    private Fixture fixtureTwoOffers() {\n        User c1 = users.save(User.create("c1-" + UUID.randomUUID(), "h", Role.CUSTOMER));\n        User c2 = users.save(User.create("c2-" + UUID.randomUUID(), "h", Role.CUSTOMER));\n        User employee = users.save(User.create("e-" + UUID.randomUUID(), "h", Role.EMPLOYEE));\n        Vehicle vehicle = vehicles.save(Vehicle.create("Honda", "Accord", 2021));\n        Offer first = offers.save(Offer.create(c1.getId(), vehicle.getId(), new BigDecimal("18000.00")));\n        Offer second = offers.save(Offer.create(c2.getId(), vehicle.getId(), new BigDecimal("17500.00")));\n        return new Fixture(employee, vehicle, first, second);\n    }\n\n    private long count(String table, String predicate) {\n        Long n = jdbc.queryForObject("SELECT count(*) FROM " + table + " WHERE " + predicate, Long.class);\n        return n == null ? 0 : n;\n    }\n\n    record Fixture(User employee, Vehicle vehicle, Offer first, Offer second) {}\n    record Result(boolean success, UUID purchaseId, String failure) {}\n}\n')
